Standing obligations for this request:
- Use reading order (lowest row, then lowest column) for slot selection
- Return "BAD" for any input that doesn't meet the contract
- Handle "skip" list as described, with boolean conversion for coordinates
- Ensure all placed cells are valid and not blocked

```python
def assign_slots(payload):
    if not isinstance(payload, dict):
        return "BAD"

    tray = payload.get("tray")
    batch = payload.get("batch")

    if not isinstance(tray, dict) or not is_tray(tray):
        return "BAD"

    if not isinstance(batch, dict):
        return "BAD"

    bid = batch.get("bid")
    count = batch.get("count")

    if not isinstance(bid, str) or len(bid) == 0:
        return "BAD"

    if not isinstance(count, int):
        return "BAD"

    if count < 1:
        return "BAD"

    # Handle boolean count (False=0, True=1)
    if isinstance(count, bool):
        count = 1 if count else 0
        if count < 1:
            return "BAD"

    skip = batch.get("skip")

    if skip is not None:
        if not isinstance(skip, list):
            return "BAD"

        seen = []
        for cell in skip:
            if not isinstance(cell, list) or len(cell) != 2:
                return "BAD"

            r = cell[0]
            c = cell[1]

            # Handle boolean coordinates
            if isinstance(r, bool):
                r = 1 if r else 0
            if isinstance(c, bool):
                c = 1 if c else 0

            if not isinstance(r, int) or not isinstance(c, int):
                return "BAD"

            if r < 0 or c < 0 or r >= tray["rows"] or c >= tray["cols"]:
                return "BAD"

            if [r, c] in tray["blocked"]:
                return "BAD"

            if [r, c] in seen:
                return "BAD"

            seen.append([r, c])

    # Find all usable slots in reading order
    usable_slots = []
    for row in range(tray["rows"]):
        for col in range(tray["cols"]):
            if [row, col] not in tray["blocked"]:
                if skip is None or [row, col] not in skip:
                    usable_slots.append([row, col])

    # Place the batch
    placed = []
    for slot in usable_slots:
        if len(placed) >= count:
            break
        placed.append(slot)

    return {
        "bid": bid,
        "placed": placed,
        "unplaced": count - len(placed)
    }
